import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    p = [n + 1] + [0] * n + [0]
    for k in range(n):
        x, y = data[1 + 2*k:3 + 2*k]
        p[x] = y
    dp = [0] * (n + 2)
    dp[0] = 1
    for b in range(1, n + 2):
        low = p[b]
        total = 0
        for a in range(b):
            high = p[a]
            if high <= low or dp[a] == 0:
                continue
            vals = [p[k] for k in range(a + 1, b) if low < p[k] < high]
            mins = []
            mn = n + 1
            for v in vals:
                mins.append(mn)
                if v < mn:
                    mn = v
            mx = 0
            valid = True
            for k in range(len(vals) - 1, -1, -1):
                v = vals[k]
                if mins[k] > v > mx:
                    valid = False
                    break
                if v > mx:
                    mx = v
            if valid:
                total += dp[a]
        dp[b] = total % MOD
    print(dp[n + 1])

if __name__ == '__main__':
    solve()

