import sys
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    bound = [[n + 1] * n for _ in range(n)]
    for i in range(2, len(data), 3):
        l, r, x = data[i:i+3]
        if r < bound[l-1][x-1]:
            bound[l-1][x-1] = r
    for l in range(n-2, -1, -1):
        row, nxt = bound[l], bound[l+1]
        for k in range(n):
            if nxt[k] < row[k]:
                row[k] = nxt[k]
    inv = [0] * (n+1)
    inv[1] = 1
    for i in range(2, n+1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD
    dp = [[0] * (n+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][i] = 1
    for l in range(n-1, -1, -1):
        row, limits = dp[l], bound[l]
        for r in range(l+1, n+1):
            total = 0
            for k in range(l, r):
                if r < limits[k]:
                    total += row[k] * dp[k+1][r]
            row[r] = total % MOD * inv[r-l] % MOD
    fact = 1
    for i in range(2, n+1):
        fact = fact * i % MOD
    print(dp[0][n] * fact % MOD)

if __name__ == '__main__':
    main()

