import sys
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, value in enumerate(data[1:]):
        p = 2
        while p * p <= value:
            if value % p == 0:
                k = 0
                while value % p == 0:
                    value //= p
                    k += 1
                factors.setdefault(p, []).append((i, k))
            p += 1
        if value > 1:
            factors.setdefault(value, []).append((i, 1))
    answer = 1
    for p, events in factors.items():
        dp = [1]
        for e, (pos, k) in enumerate(events):
            end = events[e + 1][0] if e + 1 < len(events) else n - 1
            length = end - pos
            base = pow(p, length, MOD)
            weights = [1] * (len(dp) + k)
            for j in range(1, len(weights)):
                weights[j] = weights[j - 1] * base % MOD
            shiftbase = pow(p, pos + 1, MOD)
            shifts = [1] * (k + 1)
            for j in range(1, k + 1):
                shifts[j] = shifts[j - 1] * shiftbase % MOD
            ndp = [0] * (len(dp) + k)
            for h, v in enumerate(dp):
                if v:
                    up = h + k
                    ndp[up] = (ndp[up] + v * weights[up]) % MOD
                    if h >= k:
                        down = h - k
                        ndp[down] = (ndp[down] + v * weights[down]) % MOD
                    else:
                        ndp[0] = (ndp[0] + v * shifts[k - h]) % MOD
            dp = ndp
        answer = answer * (sum(dp) % MOD) % MOD
    print(answer)

if __name__ == '__main__':
    solve()

