import sys
from functools import lru_cache


def solve():
    A, B, M = map(int, sys.stdin.buffer.read().split())
    if A > B:
        A, B = B, A

    base = B + 1
    powers = [base ** i for i in range(A)]

    @lru_cache(None)
    def dp(state):
        if state == 0:
            return 1
        answer = 0
        right = 0
        for i in range(A - 1, -1, -1):
            current = (state // powers[i]) % base
            if current > right and not (
                i == A - 2 and right > 0 and current == right + 1
            ):
                answer += dp(state - powers[i])
            right = current
        return answer % M

    state = sum(B * powers[i] for i in range(A - 1))
    state += (B - 1) * powers[-1]
    good = dp(state)

    n = A * B - 1
    factorial = 1
    for i in range(1, n + 1):
        factorial = factorial * i % M

    hooks = 1
    for row in range(B):
        length = A if row < B - 1 else A - 1
        for column in range(length):
            height = B if column < A - 1 else B - 1
            hooks = hooks * (length - column + height - row - 1) % M

    tableaux = factorial * pow(hooks, M - 2, M) % M
    print(good * tableaux % M)


if __name__ == '__main__':
    solve()

