import sys
from math import gcd

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0:2]
    processes = []
    for i in range(n):
        a, p, b, q = data[2+4*i:6+4*i]
        if p*b > q*a:
            a, p, b, q = b, q, a, p
        processes.append((a, p, b, q, a // gcd(a, b)))

    def feasible(w):
        total = 0
        for a, p, b, q, limit in processes:
            best = ((w+a-1)//a)*p
            for k in range(1, limit):
                remaining = w-k*b
                if remaining <= 0:
                    cost = k*q
                    if cost < best:
                        best = cost
                    break
                cost = k*q + ((remaining+a-1)//a)*p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget*100+1
    while high-low > 1:
        mid = (low+high)//2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    solve()

