from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        odd, even = (n + 1) // 2, n // 2
        total = fact[odd] * fact[even] * (2 if odd == even else 1)
        if k > total:
            return []
        remaining = list(range(1, n + 1))
        answer = []
        required = 1 if n % 2 else -1
        while remaining:
            for i, value in enumerate(remaining):
                parity = value % 2
                if required != -1 and parity != required:
                    continue
                next_odd = odd - parity
                next_even = even - (1 - parity)
                block = fact[next_odd] * fact[next_even]
                if k > block:
                    k -= block
                else:
                    answer.append(value)
                    remaining.pop(i)
                    odd, even = next_odd, next_even
                    required = 1 - parity
                    break
        return answer

