        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        m = (n + 1) // 2
        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            weights[i] = (powers[i] + powers[j]) % k if i != j else powers[i] % k
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])
        result = ['0'] * n
        remainder = 0
        for i, weight in enumerate(weights):
            for digit in range(9, -1 if i else 0, -1):
                value = remainder + digit * weight
                if value % suffix[i + 1] == 0:
                    result[i] = result[n - 1 - i] = str(digit)
