class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)

        def occurrences(t):
            m = len(t)
            if m == 0:
                return list(range(n + 1))
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        a, b, c = p.split('*')
        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        j = k = 0
        answer = n + 1
        for start in aa:
            end_a = start + len(a)
            while j < len(bb) and bb[j] < end_a:
                j += 1
            if j == len(bb):
                break
            end_b = bb[j] + len(b)
            while k < len(cc) and cc[k] < end_b:
                k += 1
            if k == len(cc):
                break
            answer = min(answer, cc[k] + len(c) - start)
        return answer if answer <= n else -1

