def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    for i in range(2, len(data), 3):
        x, y, z = data[i] - 1, data[i + 1] - 1, data[i + 2]
        graph[x].append((y, z))
        graph[y].append((x, z))
    del data
    dist = [-1] * n
    answer = [0] * n
    for root in range(n):
        if dist[root] != -1:
            continue
        dist[root] = 0
        component = [root]
        maximum = 0
        for u in component:
            for v, z in graph[u]:
                value = dist[u] ^ z
                if dist[v] == -1:
                    dist[v] = value
                    maximum |= value
                    component.append(v)
                elif dist[v] != value:
                    print(-1)
                    return
        mask = 0
        size = len(component)
        for bit in range(maximum.bit_length()):
            ones = sum((dist[v] >> bit) & 1 for v in component)
            if 2 * ones > size:
                mask |= 1 << bit
        for v in component:
            answer[v] = dist[v] ^ mask
    print(' '.join(map(str, answer)))

