import sys


def solve(n, a, b):
    af = a.find(b'1')
    al = a.rfind(b'1')
    bf = b.find(b'1')
    bl = b.rfind(b'1')
    gaps = []
    x = bf
    while x < bl:
        y = b.find(b'1', x + 1)
        gaps.append(y - x - 1)
        x = y
    answer = -1
    for parity in (0, 1):
        end = af + ((af - bf + parity) & 1)
        valid = True
        for gap in gaps:
            pos = end + 1
            if gap:
                start = a.find(b'0', pos)
                while start != -1:
                    stop = a.find(b'1', start)
                    if stop == -1:
                        start = -1
                        break
                    aligned = start + ((start - pos) & 1)
                    if aligned + gap <= stop:
                        pos = aligned + gap
                        break
                    start = a.find(b'0', stop)
                if start == -1:
                    valid = False
                    break
            one = a.find(b'1', pos)
            if one == -1:
                valid = False
                break
            end = one + ((one - pos) & 1)
        if valid:
            if end < al:
                end = al + ((al - end) & 1)
            k = max(0, bf - af, end - bl)
            k += (k - parity) & 1
            if answer == -1 or k < answer:
                answer = k
    return answer


