import sys
import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[0], data[1]
    groups = [[] for _ in range(W + 1)]
    for i in range(2, len(data), 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)
    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        for k in range(1, W // w + 1):
            gain = -heap[0]
            if gain <= 0:
                break
            heapq.heapreplace(heap, 2 - gain)
            for capacity in range(W, k * w - 1, -1):
                candidate = dp[capacity - w] + gain
                if candidate > dp[capacity]:
                    dp[capacity] = candidate
    print(dp[W])

if __name__ == '__main__':
    main()

