        dist=[-1]*n;dist[start]=0
        parent=[-1]*n
        q=[start]
        for v in q:
            nd=dist[v]+1
            for w in g[v]:
                if dist[w]<0:
                    dist[w]=nd;parent[w]=v;q.append(w)
        return dist,parent
    ds,parent=bfs(s)
    dt,_=bfs(t)
    d=ds[t]
    onpath=[False]*n
    v=t
    internal_branch=False
    while True:
