        if v!=s and v!=t and len(g[v])>=3:
            internal_branch=True
        if v==s:break
        v=parent[v]
    if internal_branch:
        ans=2*d+2
        for u,v in edges:
            if parent[u]==v or parent[v]==u:
                if onpath[u] and onpath[v]:
                    continue
            z=min(ds[u]+dt[v],ds[v]+dt[u])+1
            if z<=d+1:
                ans=min(ans,d+z)
        print(ans)
        return
    inf=10**18
    ans=inf
    for v in range(n):
        if len(g[v])>=3:
            ans=min(ans,2*d+4*min(ds[v],dt[v])+4)
    dist=[-1]*n;dist[s]=0
    q=[s]
    for v in q:
        for w in g[v]:
            if onpath[v] and onpath[w] and (parent[v]==w or parent[w]==v):
                continue
            if dist[w]<0:
                dist[w]=dist[v]+1;q.append(w)
    if dist[t]>=0:
        ans=min(ans,d+dist[t])
